class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        dp = [max(stayScore[0][c], max(travelScore[p][c] for p in range(n))) for c in range(n)]
        for i in range(1, k):
            nd = [0] * n
            for c in range(n):
                best = dp[c] + stayScore[i][c]
                for p in range(n):
                    cand = dp[p] + travelScore[p][c]
                    if cand > best:
                        best = cand
                nd[c] = best
            dp = nd
        return max(dp)

