class Solution {
public:
    int maxScore(int n, int k, vector<vector<int>>& stayScore, vector<vector<int>>& travelScore) {
        vector<long long> dp(n);
        for (int c = 0; c < n; c++) {
            long long best = stayScore[0][c];
            for (int p = 0; p < n; p++) best = max(best, (long long)travelScore[p][c]);
            dp[c] = best;
        }
        for (int i = 1; i < k; i++) {
            vector<long long> nd(n);
            for (int c = 0; c < n; c++) {
                long long best = dp[c] + stayScore[i][c];
                for (int p = 0; p < n; p++)
                    best = max(best, dp[p] + travelScore[p][c]);
                nd[c] = best;
            }
            dp = nd;
        }
        return (int)*max_element(dp.begin(), dp.end());
    }
};

