class Solution {
    public int maxScore(int n, int k, int[][] stayScore, int[][] travelScore) {
        long[] dp = new long[n];
        for (int c = 0; c < n; c++) {
            long best = stayScore[0][c];
            for (int p = 0; p < n; p++) best = Math.max(best, travelScore[p][c]);
            dp[c] = best;
        }
        for (int i = 1; i < k; i++) {
            long[] nd = new long[n];
            for (int c = 0; c < n; c++) {
                long best = dp[c] + stayScore[i][c];
                for (int p = 0; p < n; p++)
                    best = Math.max(best, dp[p] + travelScore[p][c]);
                nd[c] = best;
            }
            dp = nd;
        }
        long ans = 0;
        for (long v : dp) ans = Math.max(ans, v);
        return (int) ans;
    }
}

