var maxScore = function(n, k, stayScore, travelScore) {
    let dp = [];
    for (let c = 0; c < n; c++) {
        let best = stayScore[0][c];
        for (let p = 0; p < n; p++) best = Math.max(best, travelScore[p][c]);
        dp.push(best);
    }
    for (let i = 1; i < k; i++) {
        const nd = [];
        for (let c = 0; c < n; c++) {
            let best = dp[c] + stayScore[i][c];
            for (let p = 0; p < n; p++)
                best = Math.max(best, dp[p] + travelScore[p][c]);
            nd.push(best);
        }
        dp = nd;
    }
    return Math.max(...dp);
};
